"""Build both dependency-free language pages. Run from this repository's root."""
from pathlib import Path
from urllib.parse import urlencode
import html,json
ROOT=Path(__file__).resolve().parents[1]
BASE='https://jnregames.github.io'
COPY={
'en':dict(title='Galaxiga Retro Arcade Shooter for Android | JNR Games',description='Dodge alien formations, collect power-ups, and face arcade space bosses in Galaxiga for Android. Watch gameplay and get it on Google Play.',tag='ANDROID · RETRO ARCADE SPACE SHOOTER',headline='One more wave.\nOne more try.',intro='Pilot your fighter through alien formations, dodge incoming fire, and take on bosses with their own attack patterns.',download='Get it on Google Play',watch='Watch gameplay',disclosure='Contains ads and in-app purchases.',navgame='The game',navpreview='Gameplay',navupdate='Next update',switch='Español',switchurl='/es/',skip='Skip to content',featureshead='Read the attack. Find your opening.',featuresintro='Arcade space combat built around movement, timing, and the next personal best.',features=[('01','Break the formation','Watch alien enemies swoop into attack. Keep moving and find a path through the incoming fire.'),('02','Face the bosses','Learn different shooting patterns, collect power-ups, and fight for the next clear.'),('03','Chase your best','Choose your fighter, take on bonus rounds, and come back for another high-score run.')],gallery='A look inside the game',gallerynote='Actual development-build captures. The version on Google Play may look different.',captions=['Formation combat','Boss encounters','Bonus rounds'],alts=['A player fighter faces rows of colorful alien enemies.','A large alien boss faces the player beneath its health bar.','Enemy groups sweep across a bonus encounter.'],videotitle='Straight into the action',videonote='An eight-second, silent development preview. Captured in the Unity Editor; not a device-performance demonstration.',videofallback='Download the gameplay clip',updatebadge='IN DEVELOPMENT',updatetitle='Another flight is taking shape.',updatebody='We’re preparing the next Galaxiga update, with refreshed boss encounters, clearer combat effects, and a wave-pressure indicator to show when formations become more aggressive.',updatefoot='Planned changes are still being tested. Release timing and features may change.',updatecta='Play the current version',closing='Ready for your next run?',closingtext='Galaxiga Retro Arcade Shooter is available for Android.',footer='Retro space battles from JNR Games.',privacy='Privacy policy',support='Contact support',press='Press kit',previewbadge='DEVELOPMENT PREVIEW',heroalt='Galaxiga promotional artwork featuring spacecraft and alien enemies.'),
'es':dict(title='Galaxiga: juego de naves arcade para Android | JNR Games',description='Esquiva formaciones alienígenas, recoge mejoras y combate contra jefes espaciales en Galaxiga para Android. Mira el juego y descárgalo en Google Play.',tag='ANDROID · JUEGO DE NAVES ARCADE',headline='Otra oleada.\nOtro intento.',intro='Pilota tu nave entre formaciones alienígenas, esquiva los disparos y enfréntate a jefes con sus propios patrones de ataque.',download='Descargar en Google Play',watch='Ver el juego en acción',disclosure='Contiene anuncios y compras integradas.',navgame='El juego',navpreview='Vídeo',navupdate='Próxima actualización',switch='English',switchurl='/',skip='Saltar al contenido',featureshead='Observa el ataque. Encuentra un hueco.',featuresintro='Combates espaciales de estilo arcade para poner a prueba tus reflejos y superar tu propio récord.',features=[('01','Rompe la formación','Observa cómo se lanzan los enemigos hacia tu nave. Sigue moviéndote y busca un camino entre los disparos.'),('02','Enfréntate a los jefes','Aprende sus patrones de disparo, recoge mejoras y lucha por superar cada combate.'),('03','Supera tu récord','Elige tu nave, afronta las rondas de bonificación y vuelve a intentarlo para mejorar tu puntuación.')],gallery='Así se juega a Galaxiga',gallerynote='Capturas reales de una versión en desarrollo. La versión de Google Play puede tener un aspecto diferente.',captions=['Combates contra formaciones','Encuentros con jefes','Rondas de bonificación'],alts=['Una nave del jugador se enfrenta a filas de enemigos alienígenas de colores.','Un gran jefe alienígena se enfrenta al jugador bajo su barra de vida.','Grupos de enemigos recorren la pantalla durante una ronda de bonificación.'],videotitle='Directo a la acción',videonote='Avance de desarrollo de ocho segundos, sin sonido. Grabado en el editor de Unity; no demuestra el rendimiento en un teléfono.',videofallback='Descargar el vídeo',updatebadge='EN DESARROLLO',updatetitle='La próxima partida está tomando forma.',updatebody='Estamos preparando la próxima actualización de Galaxiga, con combates contra jefes renovados, efectos más claros y un indicador que muestra cuándo las formaciones se vuelven más agresivas.',updatefoot='Los cambios previstos siguen en pruebas. Las funciones y las fechas pueden cambiar.',updatecta='Jugar a la versión actual',closing='¿Listo para otra partida?',closingtext='Galaxiga Retro Arcade Shooter está disponible para Android.',footer='Batallas espaciales retro de JNR Games.',privacy='Política de privacidad',support='Contactar con asistencia',press='Material de prensa',previewbadge='AVANCE EN DESARROLLO',heroalt='Ilustración promocional de Galaxiga con naves espaciales y enemigos alienígenas.')}
for lang,c in COPY.items():
 canonical=BASE+('/es/' if lang=='es' else '/')
 ref=urlencode(dict(utm_source='website',utm_medium='organic',utm_campaign='game_page',utm_content=lang))
 store='https://play.google.com/store/apps/details?id=com.jnr.galaxiga&'+urlencode({'referrer':ref})
 link=html.escape(store,quote=True)
 features=''.join(f'<article><span class="feature-number">{n}</span><h3>{t}</h3><p>{b}</p></article>' for n,t,b in c['features'])
 gallery=''.join(f'<figure><img src="/assets/{f}.webp" alt="{a}" width="720" height="1280" loading="lazy"><figcaption>{t}</figcaption></figure>' for f,a,t in zip(['formations','boss','bonus'],c['alts'],c['captions']))
 schema={'@context':'https://schema.org','@type':'VideoGame','name':'Galaxiga Retro Arcade Shooter','url':canonical,'image':BASE+'/assets/key-art.webp','operatingSystem':'Android','genre':['Arcade','Space shooter'],'author':{'@type':'Organization','name':'JNR Games'},'sameAs':'https://play.google.com/store/apps/details?id=com.jnr.galaxiga'}
 page=f'''<!doctype html>
<html lang="{lang}"><head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<title>{c['title']}</title><meta name="description" content="{c['description']}">
<link rel="canonical" href="{canonical}"><link rel="alternate" hreflang="en" href="{BASE}/"><link rel="alternate" hreflang="es" href="{BASE}/es/"><link rel="alternate" hreflang="x-default" href="{BASE}/">
<meta property="og:type" content="website"><meta property="og:url" content="{canonical}"><meta property="og:title" content="{c['title']}"><meta property="og:description" content="{c['description']}"><meta property="og:image" content="{BASE}/assets/key-art.webp"><meta property="og:image:width" content="1024"><meta property="og:image:height" content="500"><meta name="twitter:card" content="summary_large_image">
<meta name="theme-color" content="#07111d"><link rel="icon" href="/assets/icon.webp" type="image/webp"><link rel="stylesheet" href="/assets/style.css">
<script type="application/ld+json">{json.dumps(schema,ensure_ascii=False)}</script>
</head><body><a class="skip" href="#main">{c['skip']}</a>
<header class="shell"><a class="brand" href="{'/es/' if lang=='es' else '/'}"><img src="/assets/icon.webp" width="44" height="44" alt=""><span>JNR GAMES<span class="brand-sub">GALAXIGA</span></span></a><nav aria-label="{'Principal' if lang=='es' else 'Main'}"><a href="#game">{c['navgame']}</a><a href="#preview">{c['navpreview']}</a><a class="language" href="{c['switchurl']}" lang="{'en' if lang=='es' else 'es'}" hreflang="{'en' if lang=='es' else 'es'}">{c['switch']}</a></nav></header>
<main id="main"><section class="hero shell"><div class="hero-copy"><p class="eyebrow">{c['tag']}</p><h1>{c['headline'].replace(chr(10),'<br>')}</h1><p class="lead">{c['intro']}</p><div class="actions"><a class="button primary" href="{link}"><span aria-hidden="true">▶</span> {c['download']}</a><a class="text-link" href="#preview">{c['watch']} <span aria-hidden="true">↗</span></a></div><p class="disclosure">{c['disclosure']}</p></div><div class="hero-art"><img src="/assets/key-art.webp" width="1024" height="500" alt="{c['heroalt']}" fetchpriority="high"><span class="art-caption">GALAXIGA / RETRO ARCADE SHOOTER</span></div></section>
<section class="section shell" id="game"><p class="eyebrow">GALAXIGA / ANDROID</p><h2>{c['featureshead']}</h2><p class="section-intro">{c['featuresintro']}</p><div class="features">{features}</div></section>
<section class="section shell"><div class="section-heading"><h2>{c['gallery']}</h2><p>{c['gallerynote']}</p></div><div class="gallery">{gallery}</div></section>
<section class="section shell video-section" id="preview"><div><p class="eyebrow">{c['previewbadge']}</p><h2>{c['videotitle']}</h2><p class="section-intro">{c['videonote']}</p><a class="text-link" href="/assets/gameplay-preview.mp4">{c['videofallback']} ↗</a></div><video controls playsinline preload="none" poster="/assets/video-poster.webp" width="540" height="960" aria-label="{c['videotitle']}"><source src="/assets/gameplay-preview.mp4" type="video/mp4"><a href="/assets/gameplay-preview.mp4">{c['videofallback']}</a></video></section>
<section class="section shell" id="update"><div class="update"><span class="status"><span aria-hidden="true"></span>{c['updatebadge']}</span><h2>{c['updatetitle']}</h2><p>{c['updatebody']}</p><p class="disclosure">{c['updatefoot']}</p><a class="text-link" href="{link}">{c['updatecta']} ↗</a></div></section>
<section class="closing shell"><h2>{c['closing']}</h2><p>{c['closingtext']}</p><a class="button primary" href="{link}">{c['download']} ↗</a><p class="disclosure">{c['disclosure']}</p></section></main>
<footer class="shell"><div><strong>JNR GAMES</strong><p>{c['footer']}</p></div><div class="footer-links"><a href="https://jnregames.github.io/game/privacy-policy.txt">{c['privacy']}</a><a href="mailto:recommsip@gmail.com">{c['support']}</a><a href="/assets/galaxiga-press-kit.zip">{c['press']} ↓</a></div></footer>
</body></html>'''
 (ROOT/('es/index.html' if lang=='es' else 'index.html')).write_text(page,encoding='utf-8')
print('Built English and Spanish pages')
